import { onMounted, onUnmounted } from 'vue'

/*
 * 全站尺寸都写成 rem，由根字号统一缩放（默认 1rem = 100px @1550 设计宽度）。
 *
 * 缩放规则：
 *   - 设计宽度及以上：锁在 maxRootFontSize（默认 132，DPRecorder 像素原值放大 20%）
 *   - 设计宽度往下：按视口宽度等比缩小。整页是同比例缩小的"一张图"，
 *     所以不会因为字号变大而挤出横向滚动条
 *
 * 例外页（例如 /gui/phiLink 是按 1920 宽画的）可以传入自己的设计宽度，
 * 离开时由 Layout 的 route 监听换回默认值。
 */
const DEFAULT_DESIGN_WIDTH = 1550
const DEFAULT_MAX_ROOT_FONT_SIZE = 132

/** 视口宽度 → 根字号（封顶，不设下限：下限会破坏等比缩放的版式） */
export function resolveRootFontSize(clientWidth, designWidth = DEFAULT_DESIGN_WIDTH, maxRootFontSize = DEFAULT_MAX_ROOT_FONT_SIZE) {
  return Math.min(maxRootFontSize, (clientWidth / designWidth) * maxRootFontSize)
}

export function applyRemScale(options = {}) {
  const { designWidth, maxRootFontSize } = options
  const clientWidth = document.documentElement.clientWidth
  document.documentElement.style.fontSize =
    resolveRootFontSize(clientWidth, designWidth, maxRootFontSize) + 'px'
}

/**
 * 组件里挂一次即可：挂载时算一遍，窗口尺寸变化时重算。
 * 传 { designWidth, maxRootFontSize } 可以给单个页面用另一套设计宽度。
 */
export function useRemScale(options = {}) {
  const apply = () => applyRemScale(options)

  onMounted(() => {
    apply()
    window.addEventListener('resize', apply)
  })

  onUnmounted(() => {
    window.removeEventListener('resize', apply)
  })
}
