import { reactive } from 'vue'

/**
 * 本页分区导航（仿 DPRecorder 渲染页左栏的二级目录）。
 *
 * 页面自己登记本页有哪几块内容，侧栏就把它们渲染成一组可折叠、可滚动联动的锚点：
 *   - 结构：`{ id, label, icon }` 是叶子；带 `children` 的是一级分组（DPR 的 grp-xxx / sec-xxx 两级）
 *   - `id` 必须与页面里锚点元素的 DOM id 一致，找不到元素就退化为滚回顶部，不报错
 *   - 页面在 onMounted 里 set、onUnmounted 里 clear，侧栏据此决定这一块显不显示
 *
 * 状态故意做成模块级的：Layout 与页面是两个组件实例，不需要靠 props 往下传。
 */
const state = reactive({ sections: [] })

export function setAnchorNav(sections) {
  state.sections = Array.isArray(sections) ? sections : []
}

export function clearAnchorNav() {
  state.sections = []
}

export function useAnchorNav() {
  return state
}

/** 按页面先后顺序拍平（与 DPR 的 renderOrder 同一用途：滚动联动时遍历它） */
export function flattenAnchorNav(sections) {
  const flat = []
  sections.forEach((item) => {
    flat.push(item)
    if (item.children) flat.push(...item.children)
  })
  return flat
}
