import { createRouter, createWebHashHistory } from 'vue-router'
import Layout from './layout/Layout.vue'

// 路由懒加载：每个页面单独打包成一个 chunk，打开站点时只下载 Layout 与当前页面，
// 其余页面点到哪个才下载哪个（首屏 js 体积更小，页面也各自缓存）。
const routes = [
  {
    path: '/',
    component: Layout,
    children: [
      {
        path: '',
        name: 'start',
        component: () => import(/* webpackChunkName: "page-start" */ './views/home/startPage.vue')
      },

      {
        path: 'table',
        name: 'tableMain',
        component: () => import(/* webpackChunkName: "page-tableMain" */ './views/table/tableMain.vue')
      },
      {
        path: 'table',
        children: [
          { path: 'level', name: 'tableLevel', component: () => import(/* webpackChunkName: "page-tableLevel" */ './views/table/tableLevel.vue') },
          { path: 'b30', name: 'tableB30', component: () => import(/* webpackChunkName: "page-tableB30" */ './views/table/tableB30.vue') },
          { path: 'bpm', name: 'tableBPM', component: () => import(/* webpackChunkName: "page-tableBPM" */ './views/table/tableBPM.vue') },
          //{ path: 'info', name: 'tableInfo', component: tableInfo },
          { path: 'charter', name: 'tableCharter', component: () => import(/* webpackChunkName: "page-tableCharter" */ './views/table/tableCharter.vue') },
        ]
      },
      { path: 'single/:songName?', name: 'singleMain', component: () => import(/* webpackChunkName: "page-singleMain" */ './views/single/singleMain.vue'), props: true },
      //{ path: 'account', name: 'accountMain', component: accountMain },
      { path: 'pmtMaps', name: 'pmtMain', component: () => import(/* webpackChunkName: "page-pmtMain" */ './views/pmt/pmtMain.vue') },
      { path: 'pmtStatus', name: 'pmtPlayer', component: () => import(/* webpackChunkName: "page-pmtPlayer" */ './views/pmt/pmtPlayer.vue') },
      { path: 'yfpsList', name: 'yfpsMain', component: () => import(/* webpackChunkName: "page-yfpsMain" */ './views/list/yfpsMain.vue') },
      { path: 'lvmdfList', name: 'lvmdfMain', component: () => import(/* webpackChunkName: "page-lvmdfMain" */ './views/list/lvmdfMain.vue') },
      { path: 'levelHistory', name: 'levelHistory', component: () => import(/* webpackChunkName: "page-levelHistory" */ './views/list/levelHistory.vue') },
      { path: 'about', name: 'about', component: () => import(/* webpackChunkName: "page-about" */ './views/about/AboutView.vue') },
      { path: 'guessGame', name: 'guessGame', component: () => import(/* webpackChunkName: "page-guessGame" */ './views/tool/guessGame.vue') },
      { path: 'noisePainter', name: 'noisePainter', component: () => import(/* webpackChunkName: "page-noisePainter" */ './views/tool/noisePainter.vue') },
      { path: 'signalNumber', name: 'signalNumber', component: () => import(/* webpackChunkName: "page-signalNumber" */ './views/tool/signalNumber/signalNumber.vue') },

      //{path: 'gui', name: 'gui', component: guiPage },
      {path: '/gui/phiLink', name: 'linkGUI', component: () => import(/* webpackChunkName: "page-linkGUI" */ './views/tool/linkGUI.vue') }

    ]
  },
  { path: '/:pathMatch(.*)*', redirect: { name: 'start' } }
]

const router = createRouter({
  history: createWebHashHistory(),
  routes,
  scrollBehavior() {
    return { top: 0 }
  }
})

export default router
