<script setup>
import { RouterView, useRoute, useRouter } from 'vue-router'
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'

import PageScreenshot from '../components/ui/pageShot.vue'
import { flattenAnchorNav, useAnchorNav } from '../composables/useAnchorNav.js'
import { useRemScale } from '../utils/rem.js'

// 根字号缩放（1550 设计宽度，宽于 1550 时停在 DPR 的像素原值）
useRemScale()

const route = useRoute()
const router = useRouter()

// /gui/phiLink 是全屏页面，不套外壳
const isGui = computed(() => route.path.startsWith('/gui'))

// 曲目详情页（/single/:songName）不套导航外壳，靠详情页自己的返回按钮回列表
const isSongDetail = computed(
  () => route.name === 'singleMain' && Boolean(route.params.songName)
)

/*
 * 侧栏结构逐条移植自 DPRecorder 的 .phi-nav（App.vue）：
 *   brand 行 → section（分组标题 + 缩进的叶子） → spacer → bottom section
 * 只有两处不同：站名 DPTool 仍居中在顶部（DPR 的 brand 行只有折叠按钮），
 * 以及每个一级分组都常驻侧栏（DPR 只在渲染页显示二级分区）。
 */
const sections = [

  {
    key: 'lists',
    label: '列表',
    icon: 'format-list-bulleted',
    items: [
      { name: 'singleMain', label: '曲目列表', icon: 'music-note' },
      { name: 'tableLevel', label: '定数列表', icon: 'table-large' },
      { name: 'tableCharter', label: '谱师列表', icon: 'account-edit-outline' },
      { name: 'tableBPM', label: 'BPM 列表', icon: 'speedometer' },
      { name: 'tableB30', label: 'B30 列表', icon: 'star-outline' }
    ]
  },
  {
    key: 'more',
    label: '数据',
    icon: 'view-grid-outline',
    items: [
      { name: 'pmtMain', label: 'PMT 图池', icon: 'layers-outline' },
      { name: 'pmtPlayer', label: 'PMT 赛况', icon: 'flag-outline' },
      { name: 'lvmdfMain', label: '定数变更', icon: 'history' },
      { name: 'levelHistory', label: '定数历史', icon: 'timeline-clock-outline' },
      { name: 'yfpsMain', label: '年度爱曲', icon: 'heart-outline' }
    ]
  },
  {
    key: 'tools',
    label: '工具',
    icon: 'metronome',
    items: [
      { name: 'noisePainter', label: '噪域画笔', icon: 'brush' },
      { name: 'signalNumber', label: '突脸数字', icon: 'text:18' },
      { name: 'guessGame', label: '猜曲游戏', icon: 'lightbulb-on-outline' }
    ]
  },

]

const activeItemName = computed(() => route.name)

// 页面名 = 这一页在导航里的条目名（关于页不在分组里，单独补一条）；
// 目录栏顶部拿它当标题，认不出来的路由就退回站名
const PAGE_TITLES = {}
sections.forEach((section) => {
  section.items.forEach((item) => {
    PAGE_TITLES[item.name] = item.label
  })
})
PAGE_TITLES.about = '关于'

const currentPageLabel = computed(() => PAGE_TITLES[route.name] || 'DPTool')


const readLocal = (key, fallback) => {
  try {
    const value = localStorage.getItem(key)
    return value === null ? fallback : value
  } catch (e) {
    // 隐私模式下 localStorage 不可用，忽略即可
    return fallback
  }
}

const writeLocal = (key, value) => {
  try {
    localStorage.setItem(key, value)
  } catch (e) {
    // 同上
  }
}

/* ---------- 抽屉开合 ---------- */
// 导航做成左侧抽屉：默认收起，点左边缘的悬浮页签拉开，点遮罩 / Esc / 跳转后自动收回
const drawerOpen = ref(false)

const navCollapsed = computed(() => !drawerOpen.value)

const toggleCollapsed = () => {
  drawerOpen.value = !drawerOpen.value
  if (drawerOpen.value) anchorOpen.value = false
}

const closeDrawer = () => {
  drawerOpen.value = false
}

/* ---------- 分组的展开状态 ---------- */
const GROUPS_KEY = 'dpt-nav-groups'

// 存「被收起的分组 key」，没记录的默认展开
const navGroupOpen = ref((() => {
  const raw = readLocal(GROUPS_KEY, '')
  if (!raw) return {}
  try {
    const parsed = JSON.parse(raw)
    if (!Array.isArray(parsed)) return {}
    const state = {}
    parsed.forEach((key) => {
      state[key] = false
    })
    return state
  } catch (e) {
    return {}
  }
})())

const isGroupOpen = (key) => navGroupOpen.value[key] !== false

const saveGroups = () => {
  const closed = Object.keys(navGroupOpen.value).filter((key) => navGroupOpen.value[key] === false)
  writeLocal(GROUPS_KEY, JSON.stringify(closed))
}

// 点分组标题：展开 / 收起该组的叶子
const onGroupClick = (section) => {
  navGroupOpen.value = { ...navGroupOpen.value, [section.key]: !isGroupOpen(section.key) }
  saveGroups()
}

// 切页时把当前页面所在分组展开，避免选中项被自己藏起来
watch(
  () => route.name,
  (name) => {
    const section = sections.find((s) => s.items.some((item) => item.name === name))
    if (section && !isGroupOpen(section.key)) {
      navGroupOpen.value = { ...navGroupOpen.value, [section.key]: true }
      saveGroups()
    }
  }
)


/* ---------- 页面自己的分区目录（仿 DPR 渲染页左栏的二级子项） ---------- */
const anchorNav = useAnchorNav()
const anchorFlat = computed(() => flattenAnchorNav(anchorNav.sections))

const ANCHOR_GROUPS_KEY = 'dpt-anchor-groups'
const anchorGroupOpen = ref((() => {
  const raw = readLocal(ANCHOR_GROUPS_KEY, '')
  if (!raw) return {}
  try {
    const parsed = JSON.parse(raw)
    if (!Array.isArray(parsed)) return {}
    const state = {}
    parsed.forEach((key) => {
      state[key] = false
    })
    return state
  } catch (e) {
    return {}
  }
})())

const isAnchorGroupOpen = (key) => anchorGroupOpen.value[key] !== false

const saveAnchorGroups = () => {
  const closed = Object.keys(anchorGroupOpen.value).filter((key) => anchorGroupOpen.value[key] === false)
  writeLocal(ANCHOR_GROUPS_KEY, JSON.stringify(closed))
}

// 当前滚到的分区（点侧栏 / 滚动联动都写这个）
const activeAnchor = ref('')

// 点击后短暂屏蔽联动：平滑滚动途中会一路经过别的分区，不屏蔽的话高亮会被沿途抢走
let anchorSpyMuteUntil = 0

const scrollToAnchor = (id) => {
  activeAnchor.value = id
  anchorSpyMuteUntil = Date.now() + 900
  const el = document.getElementById(id)
  if (el) {
    el.scrollIntoView({ behavior: 'smooth', block: 'start' })
    return
  }
  // 锚点不存在就退化为回顶部，不报错
  centerRef.value?.scrollTo({ top: 0, behavior: 'smooth' })
}

// 组标题：展开/收起并滚到该组
const onAnchorGroupClick = (item) => {
  anchorGroupOpen.value = { ...anchorGroupOpen.value, [item.id]: !isAnchorGroupOpen(item.id) }
  saveAnchorGroups()
  scrollToAnchor(item.id)
}

const centerRef = ref(null)

/**
 * 滚动联动：监听的是捕获阶段的 document scroll，
 * 这样不管实际滚动的是 .phi-center 还是别的容器都能收到。
 */
let anchorSpyFrame = 0
const onAnyScroll = () => {
  if (Date.now() < anchorSpyMuteUntil) return
  if (anchorSpyFrame) return
  anchorSpyFrame = requestAnimationFrame(() => {
    anchorSpyFrame = 0
    const scroller = centerRef.value
    if (!scroller || !anchorFlat.value.length) return
    // 判定线：内容区顶部往下 28px
    const line = scroller.getBoundingClientRect().top + 28
    let current = anchorFlat.value[0].id
    anchorFlat.value.forEach((item) => {
      const el = document.getElementById(item.id)
      if (el && el.getBoundingClientRect().top <= line) current = item.id
    })
    activeAnchor.value = current
  })
}

// 换页 / 换了分区表：默认高亮第一项
watch(
  () => anchorNav.sections,
  (sections) => {
    activeAnchor.value = sections.length ? sections[0].id : ''
  },
  { immediate: true }
)

onMounted(() => {
  document.addEventListener('scroll', onAnyScroll, true)
})

onUnmounted(() => {
  document.removeEventListener('scroll', onAnyScroll, true)
  window.removeEventListener('pointermove', onAnchorDragMove)
  window.removeEventListener('pointerup', stopAnchorDrag)
  if (anchorSpyFrame) cancelAnimationFrame(anchorSpyFrame)
})

/* ---------- 二级导航（本页目录）浮窗 ---------- */
// 入口挂在主导航入口正下方；只有本页登记了分区目录（anchorNav）才显示
const anchorOpen = ref(false)
const hasAnchorNav = computed(() => anchorNav.sections.length > 0)

/* 入口按钮固定在左上角，点一下开/关目录浮窗 */
const SUB_TAB_GAP = 8
const subTabRef = ref(null)

const measureSubTab = () => subTabRef.value?.getBoundingClientRect() || null

// 浮窗永远从按钮下方展开：按钮是唯一的定位锚



const toggleAnchorPanel = () => {
  if (anchorOpen.value) {
    anchorOpen.value = false
    return
  }
  // 两个面板共用左边缘的按钮列，同屏只留一个：开目录栏就把抽屉收回去
  drawerOpen.value = false
  anchorOpen.value = true
}

// 点目录项：滚到锚点后收起浮窗，避免挡住内容
const pickAnchor = (id) => {
  scrollToAnchor(id)
  anchorOpen.value = false
}

watch(
  () => route.name,
  () => {
    anchorOpen.value = false
  }
)

/* ---------- 跳转 ---------- */
const goHome = () => {
  router.push({ name: 'start' })
}

// 详情页的返回：回曲目列表（不是浏览器后退，避免从外部直接进详情时退出去）
const goBackToSongs = () => {
  router.push({ name: 'singleMain' })
}

const goItem = (item) => {
  router.push({ name: item.name })
}
</script>

<template>
  <PageScreenshot />

  <div v-if="isGui" class="gui-root">
    <RouterView />
  </div>

  <div v-else class="dt-frame" :class="{ 'dt-frame--subnav': hasAnchorNav, 'dt-frame--plain': isSongDetail }">
    <!-- 导航入口：贴在左边缘的长条，抽屉开着时也留在最上层，再点一次收起 -->
    <!-- 曲目详情页没有导航，只留一个返回按钮 -->
    <button
      v-if="isSongDetail"
      class="dt-drawer-tab dt-drawer-tab--back"
      type="button"
      title="返回曲目列表"
      @click="goBackToSongs"
    >
      <i class="mdi mdi-chevron-left"></i>
    </button>

    <button
      v-if="!isSongDetail"
      class="dt-drawer-tab"
      :class="{ 'dt-drawer-tab--on': drawerOpen }"
      type="button"
      :title="drawerOpen ? '收起导航' : '展开导航'"
      @click="toggleCollapsed"
    >
      <i class="mdi" :class="drawerOpen ? 'mdi-chevron-left' : 'mdi-chevron-right'"></i>
    </button>

    <!-- 目录入口：本页登记了分区目录才出现，位置紧贴导航入口正下方。
         与导航入口一样常驻，抽屉/目录栏打开时按钮不消失（它是唯一的关闭处） -->
    <button
      v-if="hasAnchorNav && !isSongDetail"
      ref="subTabRef"
      class="dt-drawer-tab dt-drawer-tab--sub"
      :class="{ 'dt-drawer-tab--on': anchorOpen }"
      type="button"
      title="本页目录"
      @click="toggleAnchorPanel"
    >
      <i class="mdi mdi-format-list-bulleted"></i>
    </button>

    <div v-if="anchorOpen" class="dt-anchor-mask" @click="anchorOpen = false"></div>

    <div v-if="anchorOpen" class="dt-anchor-panel">
      <!-- 顶部标题：当前页在导航里的条目名，与抽屉 brand 行同高、同样居中 -->
      <div class="dt-anchor-panel__head">
        <span class="dt-anchor-panel__title">{{ currentPageLabel }}</span>
      </div>

      <nav class="dt-anchor-panel__list">
        <template v-for="item in anchorNav.sections" :key="item.id">
          <button
            v-if="!item.children"
            class="dt-anchor-panel__item"
            :class="{ 'dt-anchor-panel__item--active': activeAnchor === item.id }"
            type="button"
            @click="pickAnchor(item.id)"
          >
            <span class="dt-anchor-panel__label">{{ item.label }}</span>
          </button>

          <template v-else>
            <button
              class="dt-anchor-panel__item dt-anchor-panel__item--group"
              :class="{ 'dt-anchor-panel__item--active': activeAnchor === item.id }"
              type="button"
              @click="onAnchorGroupClick(item)"
            >
              <span class="dt-anchor-panel__label">{{ item.label }}</span>
              <i
                class="mdi dt-anchor-panel__caret"
                :class="isAnchorGroupOpen(item.id) ? 'mdi-chevron-up' : 'mdi-chevron-down'"
              ></i>
            </button>
            <button
              v-for="leaf in item.children"
              v-show="isAnchorGroupOpen(item.id)"
              :key="leaf.id"
              class="dt-anchor-panel__item dt-anchor-panel__item--leaf"
              :class="{ 'dt-anchor-panel__item--active': activeAnchor === leaf.id }"
              type="button"
              @click="pickAnchor(leaf.id)"
            >
              <span class="dt-anchor-panel__label">{{ leaf.label }}</span>
            </button>
          </template>
        </template>
      </nav>
    </div>

    <div v-if="drawerOpen && !isSongDetail" class="dt-drawer-mask" @click="closeDrawer"></div>

    <aside v-if="!isSongDetail" class="phi-nav" :class="{ 'phi-nav--open': drawerOpen }">
      <!-- brand 行：只有居中的站名（点它回首页），收起抽屉改由左边缘的长条负责 -->
      <div class="phi-nav__brand">
        <button class="phi-nav__home" type="button" title="回到首页" @click="goHome">
          <img class="phi-nav__logo" src="/favicon.png" alt="" />
          <span class="phi-nav__name">DPTool</span>
        </button>
      </div>

      <nav class="phi-nav__section">
        <template v-for="section in sections" :key="section.key">
          <!-- 一级分组：图标 + 组名 + 右端展开箭头（DPR 的 --group） -->
          <button
            class="phi-nav__item phi-nav__item--sub phi-nav__item--group"
            type="button"
            @click="onGroupClick(section)"
          >
            <i class="mdi" :class="`mdi-${section.icon}`"></i>
            <span class="phi-nav__label">{{ section.label }}</span>
            <i
              class="mdi phi-nav__caret"
              :class="isGroupOpen(section.key) ? 'mdi-chevron-up' : 'mdi-chevron-down'"
            ></i>
          </button>

          <!-- 叶子条目：缩进一级，字号与图标小一档（DPR 的 --leaf） -->
          <button
            v-for="item in section.items"
            v-show="isGroupOpen(section.key)"
            :key="item.name"
            class="phi-nav__item phi-nav__item--leaf"
            :class="{ 'phi-nav__item--active': activeItemName === item.name }"
            type="button"
            @click="goItem(item)"
          >
            <span v-if="item.icon.startsWith('text:')" class="phi-nav__digit">{{ item.icon.slice(5) }}</span>
            <i v-else class="mdi" :class="`mdi-${item.icon}`"></i>
            <span class="phi-nav__label">{{ item.label }}</span>
          </button>
        </template>
      </nav>

      <div class="phi-nav__spacer"></div>

      <nav class="phi-nav__section phi-nav__section--bottom">
        <button
          class="phi-nav__item"
          :class="{ 'phi-nav__item--active': activeItemName === 'about' }"
          type="button"
          title="关于"
          @click="goItem({ name: 'about' })"
        >
          <i class="mdi mdi-information-outline"></i>
          <span class="phi-nav__label">关于</span>
        </button>
      </nav>
    </aside>

    <main ref="centerRef" class="phi-center">
      <RouterView />
    </main>
  </div>
</template>

<style scoped>
/* ============================================================
   以下侧栏样式逐条移植自 DPRecorder 的 App.vue（.phi-nav 一节），
   只把令牌前缀换成 --dt-*、px 换成 rem（1rem = 100px @1550）。
   ============================================================ */

.dt-frame {
  position: relative;
  display: flex;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: var(--dt-bg-base);
}

/*
