  width: var(--dt-nav-width);
  max-width: 82vw;
  padding: var(--dt-space-2) var(--dt-nav-inline-padding) var(--dt-space-3)
    var(--dt-nav-rail-offset);
  overflow-x: hidden;
  overflow-y: auto;
  background: var(--dt-panel-translucent);
  border: 0.5px solid var(--dt-border-l3);
  border-left: none;
  border-top: none;
  border-bottom: none;
  border-radius: 0 var(--dt-radius-sm) var(--dt-radius-sm) 0;
  box-shadow: var(--dt-shadow-lg);
  backdrop-filter: blur(var(--dt-space-3));
  user-select: none;
  -webkit-user-select: none;
  transform: translateX(calc(-100% - 0.1rem));
  transition: transform var(--dt-dur) var(--dt-ease-out);
}

.phi-nav--open {
  transform: none;
}

/* 入口按钮：钉在左边缘的窄长条（半透明），抽屉/目录栏开着时也留在最上层，
   再点一次就是收起 —— 所以侧栏里不再另设收起按钮 */
