  padding: 0 0 var(--dt-space-2)
    calc(var(--dt-nav-rail-offset) - var(--dt-nav-inline-padding));
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--dt-border-l2) transparent;
}

/* 目录条目按侧栏的行式排版：同样的圆角、hover 底色与缩进 */
.dt-anchor-panel__item {
