/*
 * 导出文件名统一成「工具名_时间_其他参数.ext」。
 *
 * 时间取本地时间 yyyyMMdd-HHmmss：里面不含下划线，所以按 "_" 切分时
 * 第一段永远是工具名、第二段永远是时间，后面的参数顺序不限。
 * 参数片段里的 \ / : * ? " < > | 和空白会被去掉，空片段自动跳过
 * （源图名可能为空，或者不含扩展名，这两种情况都不会留下多余的下划线）。
 */
const pad = value => String(value).padStart(2, '0')

export function timeStamp(date = new Date()) {
  return `${date.getFullYear()}${pad(date.getMonth() + 1)}${pad(date.getDate())}-${pad(date.getHours())}${pad(date.getMinutes())}${pad(date.getSeconds())}`
}

export function exportFileName(tool, extras = [], ext = 'png', date = new Date()) {
  const clean = value => String(value ?? '').replace(/[\\/:*?"<>|\s]+/g, '')
  const parts = [tool, timeStamp(date), ...extras].map(clean).filter(Boolean)
  return `${parts.join('_')}.${ext}`
}
